using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddChatClient(chatClientBuilder =>
    chatClientBuilder.UseOpenAIChatClient(
        builder.Configuration["AI:Model"] ?? "gpt-4o-mini-2024-07-18"));

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();

// Define tools the agent can use
var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearch),
    AIFunctionFactory.Create(SaveNote),
    AIFunctionFactory.Create(GetNotes),
};

// Create the research agent using Microsoft Agent Framework
var agent = chatClient.AsAIAgent(
    instructions: """
        You are a research agent. When given a topic, you:
        1. Search the web multiple times to gather information from different angles.
        2. Save important findings as notes using the note-taking tool.
        3. After gathering enough information, retrieve all your notes and produce a 
           comprehensive summary of your findings.
        Always search at least 2-3 times with different queries before summarizing.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and summarizing findings.",
    tools: tools);

// Get the research topic
var topic = args.Length > 0
    ? string.Join(' ', args)
    : "the latest advances in quantum computing in 2026";

Console.WriteLine($"🔍 Researching: {topic}\n");

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session: null,
    options: new ChatClientAgentRunOptions(new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    }));

Console.WriteLine("📋 Research Summary:\n");
Console.WriteLine(response.Text);

// --- Tool implementations ---

// In-memory note storage for the session
var notes = new List<string>();

[Description("Searches the web for information on a query. Returns relevant search results.")]
static string WebSearch([Description("The search query to look up")] string query)
{
    // Simulated web search results for demonstration.
    // In production, replace with a real search API (e.g., Bing Search).
    return $"""
        Search results for: "{query}"

        1. [Research Article] Recent developments related to '{query}' show significant progress 
           in the field. Key findings include new methodologies and breakthroughs reported by 
           leading institutions.

        2. [News Report] Industry experts have noted that '{query}' is an area of active 
           research with multiple teams worldwide contributing novel approaches.

        3. [Academic Paper] A comprehensive review of '{query}' highlights both theoretical 
           advances and practical applications emerging in recent months.
        """;
}

[Description("Saves an important research finding as a note for later reference.")]
string SaveNote(
    [Description("A title for the note")] string title,
    [Description("The content of the note")] string content)
{
    notes.Add($"[{title}]: {content}");
    return $"Note saved: '{title}' ({notes.Count} total notes)";
}

[Description("Retrieves all saved research notes.")]
string GetNotes()
{
    if (notes.Count == 0)
        return "No notes saved yet.";

    return "Saved research notes:\n" + string.Join("\n\n", notes.Select((n, i) => $"{i + 1}. {n}"));
}

